import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 크기 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr02701Controller {
  @Get('/portal/widgets')
  async listPortalWidgets(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const rawPage = query['page'];
    const rawSize = query['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    const size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const offset = page * limit;
    return transaction(async (db) => {
      // 본인 설정만 조회한다 (BEHAVIOR.md 값의 출처: 현재 사용자)
      const items = await db.query(
        `SELECT component_type AS "componentType",
                component_key AS "componentKey",
                menu_id AS "menuId",
                visible_yn AS "visibleYn",
                sort_order AS "sortOrder"
           FROM portal_personalization
          WHERE employee_id = CAST(:userId AS bigint)
          ORDER BY sort_order ASC NULLS LAST, portal_personalization_id ASC
          LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)`,
        { userId: user.id, limit, offset },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM portal_personalization
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      const total = Number(counts[0]['total']);
      return { items, page, size: limit, total };
    });
  }
}

