import { useState } from 'react';
import type { PageProps, Row, Column, Page as PageData } from '../kit';
import {
  call,
  useData,
  Badge,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Field,
  Select,
  RefName,
  ErrorText,
} from '../kit';

const TYPE_LABEL: Record<string, string> = {
  WIDGET: '위젯',
  BANNER: '배너',
  MENU: '메뉴',
};

const TYPE_OPTIONS: [string, string][] = [
  ['WIDGET', '위젯'],
  ['BANNER', '배너'],
  ['MENU', '메뉴'],
];

const SIZE = 20;

export default function FnSfr02701Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [typeInput, setTypeInput] = useState('');
  const [type, setType] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const { data, error, loading } = useData<PageData>(
    () => call<PageData>('GET', '/portal/widgets', role, undefined, { page, size: SIZE }),
    [page, role],
  );

  const items = data ? data.items : [];
  const rows = type ? items.filter((r) => r.componentType === type) : items;
  const visibleCount = items.filter((r) => r.visibleYn === true).length;
  const hiddenCount = items.length - visibleCount;

  const columns: Column[] = [
    {
      key: 'componentType',
      label: '구성 유형',
      render: (r) => <>{TYPE_LABEL[String(r.componentType)] ?? String(r.componentType)}</>,
    },
    {
      key: 'componentKey',
      label: '구성 식별값',
      render: (r) => <>{r.componentKey ? String(r.componentKey) : '-'}</>,
    },
    {
      key: 'menuId',
      label: '메뉴',
      render: (r) =>
        r.menuId ? <RefName table="menu" role={role} value={r.menuId} /> : <>-</>,
    },
    {
      key: 'visibleYn',
      label: '표시 여부',
      render: (r) => <Badge value={r.visibleYn === true ? '표시' : '숨김'} />,
    },
    { key: 'sortOrder', label: '배치 순서' },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>구성 현황</h2>
        <Tiles
          items={[
            ['전체 구성', data ? data.total : 0],
            ['표시 중 (현재 쪽)', visibleCount],
            ['숨김 (현재 쪽)', hiddenCount],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>포털 위젯 구성</h2>
        <Filters
          onSearch={() => setType(typeInput)}
          onReset={() => {
            setTypeInput('');
            setType('');
          }}
        >
          <Field label="구성 유형">
            <Select
              value={typeInput}
              onChange={setTypeInput}
              options={TYPE_OPTIONS}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={rows.length} />
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty="저장된 개인화 설정이 없습니다. 기본 구성으로 표시됩니다."
        />
        <Pager
          page={data ? data.page : page}
          size={data ? data.size : SIZE}
          total={data ? data.total : 0}
          onPage={setPage}
        />
      </section>

      <section className="box span-4">
        <h2>표시 중인 구성</h2>
        <DataTable
          columns={[
            {
              key: 'componentKey',
              label: '구성',
              render: (r) => (
                <>
                  {r.componentKey
                    ? String(r.componentKey)
                    : TYPE_LABEL[String(r.componentType)] ?? '-'}
                </>
              ),
            },
            { key: 'sortOrder', label: '순서' },
          ]}
          rows={items.filter((r) => r.visibleYn === true)}
          onRowClick={(r) => setDetail(r)}
          empty="표시 중인 구성이 없습니다."
        />
      </section>

      {detail ? (
        <Drawer title="구성 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['구성 유형', TYPE_LABEL[String(detail.componentType)] ?? String(detail.componentType)],
              ['구성 식별값', detail.componentKey ? String(detail.componentKey) : '-'],
              [
                '메뉴',
                detail.menuId ? (
                  <RefName table="menu" role={role} value={detail.menuId} />
                ) : (
                  '-'
                ),
              ],
              ['표시 여부', <Badge value={detail.visibleYn === true ? '표시' : '숨김'} />],
              ['배치 순서', detail.sortOrder === null || detail.sortOrder === undefined ? '-' : String(detail.sortOrder)],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
